import{_ as s,o as n,c as e,am as p}from"./chunks/framework._FJXuPhs.js";const u=JSON.parse('{"title":"核心特性","description":"","frontmatter":{"title":"核心特性","excerpt":"Java基础_基础内容03","date":"2024-01-08 14:06:02","updated":"2024-01-08 14:06:02"},"headers":[],"relativePath":"基础/语法基础/核心特性.md","filePath":"基础/语法基础/核心特性.md","lastUpdated":null}'),l={name:"基础/语法基础/核心特性.md"};function i(t,a,c,o,r,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h3 id="_1、异常" tabindex="-1">1、异常 <a class="header-anchor" href="#_1、异常" aria-label="Permalink to &quot;1、异常&quot;">​</a></h3><h4 id="基础概念" tabindex="-1">基础概念 <a class="header-anchor" href="#基础概念" aria-label="Permalink to &quot;基础概念&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202401181322703.png" alt="image.png"></p><h5 id="try-catch-finally" tabindex="-1">try-catch-finally <a class="header-anchor" href="#try-catch-finally" aria-label="Permalink to &quot;try-catch-finally&quot;">​</a></h5><blockquote><p>try-catch-finally 中哪个部分可以省略</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 示例：try-catch-finally结构</span></span>
<span class="line"><span>try {</span></span>
<span class="line"><span>    // 代码块，可能会产生异常</span></span>
<span class="line"><span>} catch (ExceptionType1 e) {</span></span>
<span class="line"><span>    // 处理ExceptionType1异常</span></span>
<span class="line"><span>} catch (ExceptionType2 e) {</span></span>
<span class="line"><span>    // 处理ExceptionType2异常</span></span>
<span class="line"><span>} finally {</span></span>
<span class="line"><span>    // 清理代码，总是会执行</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在Java中的<code>try-catch-finally</code>异常处理结构中：</p><ol><li><strong><code>try</code>块</strong>: <ul><li>不可省略。必须有<code>try</code>块，因为它定义了可能产生异常的代码段。</li></ul></li><li><strong><code>catch</code>块</strong>: <ul><li>可以省略，但如果省略<code>catch</code>块，必须有<code>finally</code>块。</li><li>如果<code>try</code>块中的代码可能抛出异常，通常需要至少一个<code>catch</code>块来处理这些异常。</li></ul></li><li><strong><code>finally</code>块</strong>: <ul><li>可以省略，但如果省略<code>finally</code>块，必须有至少一个<code>catch</code>块。</li><li><code>finally</code>块用于执行清理操作，无论是否捕获到异常，<code>finally</code>块总是会执行。</li></ul></li></ol><p>因此，可以省略<code>catch</code>块或<code>finally</code>块中的任何一个，但不能两个都省略。你至少需要<code>try</code>和<code>catch</code>，或者<code>try</code>和<code>finally</code>组合。</p><hr><h4 id="checked-exception-和-unchecked-exception" tabindex="-1">Checked Exception 和 Unchecked Exception <a class="header-anchor" href="#checked-exception-和-unchecked-exception" aria-label="Permalink to &quot;Checked Exception 和 Unchecked Exception&quot;">​</a></h4><p><strong>Checked Exception</strong> 即 受检查异常 ，Java 代码在编译过程中，如果受检查异常没有被 <code>catch</code>或者<code>throws</code> 关键字处理的话，就没办法通过编译。</p><p>比如下面这段 IO 操作的代码：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202401181324094.png" alt="image.png"></p><p>除了<code>RuntimeException</code>及其子类以外，其他的<code>Exception</code>类及其子类都属于受检查异常 。常见的受检查异常有：IO 相关的异常、<code>ClassNotFoundException</code>、<code>SQLException</code>...。</p><p><strong>Unchecked Exception</strong> 即 <strong>不受检查异常</strong> ，Java 代码在编译过程中 ，我们即使不处理不受检查异常也可以正常通过编译。</p><p><code>RuntimeException</code> 及其子类都统称为非受检查异常，常见的有（建议记下来，日常开发中会经常用到）：</p><ul><li><code>NullPointerException</code>(空指针错误)</li><li><code>IllegalArgumentException</code>(参数错误比如方法入参类型错误)</li><li><code>NumberFormatException</code>（字符串转换为数字格式错误，<code>IllegalArgumentException</code>的子类）</li><li><code>ArrayIndexOutOfBoundsException</code>（数组越界错误）</li><li><code>ClassCastException</code>（类型转换错误）</li><li><code>ArithmeticException</code>（算术错误）</li><li><code>SecurityException</code> （安全错误比如权限不够）</li><li><code>UnsupportedOperationException</code>(不支持的操作错误比如重复创建同一用户)</li><li>……</li></ul><h5 id="空指针异常" tabindex="-1">空指针异常 <a class="header-anchor" href="#空指针异常" aria-label="Permalink to &quot;空指针异常&quot;">​</a></h5><p>空指针异常是不受检测异常下运行期异常中的一种；当我们在尝试使用 null 引用的时候，会发生 NPE。</p><p>最基础也是比较需要注意的一个情况是字符串比较，在字符串比较的时候，保证常量放前面</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202401311055211.png" alt="image.png"></p><blockquote><p>如何避免指针异常</p></blockquote><ul><li><ol><li>在使用之前先检查一下是否为 null</li></ol></li><li><ol start="2"><li>调用方法的时候进行参数检查</li></ol></li><li><ol start="3"><li>在设计方法或者API 的时候，尽量不要返回 null 值，而且返回一个空集合或者默认值；</li></ol></li><li><ol start="4"><li>初始化使用字段，保证不为 null</li></ol></li><li><ol start="5"><li>使用 Optional</li></ol></li><li><ol start="6"><li>使用断言（开发和测试环境）</li></ol></li></ul><p>使用示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 示例：避免空指针异常的方法</span></span>
<span class="line"><span>public class NullPointerAvoidance {</span></span>
<span class="line"><span>    public static void main(String[] args) {</span></span>
<span class="line"><span>        String str = null;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 1. 检查是否为 null</span></span>
<span class="line"><span>        if (str != null) {</span></span>
<span class="line"><span>            System.out.println(str.length());</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 2. 使用Optional类（Java 8+）</span></span>
<span class="line"><span>        Optional&lt;String&gt; optionalStr = Optional.ofNullable(str);</span></span>
<span class="line"><span>        optionalStr.ifPresent(System.out::println);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 3. 安全调用方法（例如使用Apache Commons Lang）</span></span>
<span class="line"><span>        int length = StringUtils.length(str); // 安全的，不会抛出空指针异常</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 4. 使用断言（仅在开发和测试环境中）</span></span>
<span class="line"><span>        assert str != null : &quot;字符串不应该为 null&quot;;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><hr><h4 id="throwable-类常用方法" tabindex="-1">Throwable 类常用方法 <a class="header-anchor" href="#throwable-类常用方法" aria-label="Permalink to &quot;Throwable 类常用方法&quot;">​</a></h4><ul><li><code>String getMessage()</code>: 返回异常发生时的简要描述</li><li><code>String toString()</code>: 返回异常发生时的详细信息</li><li><code>String getLocalizedMessage()</code>: 返回异常对象的本地化信息。使用 <code>Throwable</code> 的子类覆盖这个方法，可以生成本地化信息。如果子类没有覆盖该方法，则该方法返回的信息与 <code>getMessage()</code>返回的结果相同</li><li><code>void printStackTrace()</code>: 在控制台上打印 <code>Throwable</code> 对象封装的异常信息</li></ul><h3 id="_2、泛型" tabindex="-1">2、泛型 <a class="header-anchor" href="#_2、泛型" aria-label="Permalink to &quot;2、泛型&quot;">​</a></h3><h4 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to &quot;基本用法&quot;">​</a></h4><p><strong>Java 泛型（Generics）</strong> 是 JDK 5 中引入的一个新特性。</p><p>一般有三种使用方式:<strong>泛型类</strong>、<strong>泛型接口</strong>、<strong>泛型方法</strong></p><blockquote><p>泛型类</p></blockquote><p>定义</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//此处T可以随便写为任意标识，常见的如T、E、K、V等形式的参数常用于表示泛型</span></span>
<span class="line"><span>//在实例化泛型类时，必须指定T的具体类型</span></span>
<span class="line"><span>public class Generic&lt;T&gt;{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    private T key;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public Generic(T key) {</span></span>
<span class="line"><span>        this.key = key;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public T getKey(){</span></span>
<span class="line"><span>        return key;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generic&lt;Integer&gt; genericInteger = new Generic&lt;Integer&gt;(123456);</span></span></code></pre></div><blockquote><p>泛型接口</p></blockquote><p>定义</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public interface Generator&lt;T&gt; {</span></span>
<span class="line"><span>    public T method();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>实现泛型接口，不指定类型：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class GeneratorImpl&lt;T&gt; implements Generator&lt;T&gt;{</span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public T method() {</span></span>
<span class="line"><span>        return null;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>实现泛型接口，指定类型：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class GeneratorImpl&lt;T&gt; implements Generator&lt;String&gt;{</span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public String method() {</span></span>
<span class="line"><span>        return &quot;hello&quot;;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>泛型方法</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   public static &lt; E &gt; void printArray( E[] inputArray )</span></span>
<span class="line"><span>   {</span></span>
<span class="line"><span>         for ( E element : inputArray ){</span></span>
<span class="line"><span>            System.out.printf( &quot;%s &quot;, element );</span></span>
<span class="line"><span>         }</span></span>
<span class="line"><span>         System.out.println();</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 创建不同类型数组：Integer, Double 和 Character</span></span>
<span class="line"><span>Integer[] intArray = { 1, 2, 3 };</span></span>
<span class="line"><span>String[] stringArray = { &quot;Hello&quot;, &quot;World&quot; };</span></span>
<span class="line"><span>printArray( intArray  );</span></span>
<span class="line"><span>printArray( stringArray  );</span></span></code></pre></div><blockquote><p>注意：静态泛型方法是没有办法使用类上声明的泛型的。只能使用自己声明的 <code>&lt;E&gt;</code> （静态方法的加载在类前面）</p></blockquote><h4 id="类型擦除、通配符" tabindex="-1">类型擦除、通配符 <a class="header-anchor" href="#类型擦除、通配符" aria-label="Permalink to &quot;类型擦除、通配符&quot;">​</a></h4><p>to be contined...</p><h3 id="_3、反射" tabindex="-1">3、反射 <a class="header-anchor" href="#_3、反射" aria-label="Permalink to &quot;3、反射&quot;">​</a></h3><blockquote><p>反射是什么</p></blockquote><p>Java反射是一种强大的机制，它允许程序在运行时检查或修改Java虚拟机中的类的行为。基本上，反射使得程序可以操作那些在编译时还不知道的类和对象。</p><p>使用场景：像我们常用的框架 Spring/Spring Boot、MyBatis 都大量使用了动态代理，而动态代理的实现也依赖于反射。</p><p><strong>理解Java反射</strong></p><ul><li><strong>动态性</strong>: 反射的核心是动态性。它使得你可以在运行时动态地创建对象、调用方法、访问字段，而不必在编译时具体知道类的名称和方法。</li><li><strong>API</strong>: Java反射的功能主要通过<code>java.lang.Class</code>类及<code>java.lang.reflect</code>包中的类（如<code>Method</code>、<code>Field</code>、<code>Constructor</code>等）提供。</li><li><strong>类元数据</strong>: 反射允许程序获取任何类的内部信息，包括类的成员方法、字段、构造函数、注解等。</li></ul><blockquote><p>为什么你使用 Spring 的时候 ，一个<code>@Component</code>注解就声明了一个类为 Spring Bean 呢？为什么你通过一个 <code>@Value</code>注解就读取到配置文件中的值呢？究竟是怎么起作用的呢？</p></blockquote><p>这些都是因为你可以基于反射分析类，然后获取到类/属性/方法/方法的参数上的注解。你获取到注解之后，就可以做进一步的处理。</p><blockquote><p>反射的优缺点：</p></blockquote><ul><li>优点：强大和灵活</li><li>缺点： <ul><li>性能开销较大，使用不当可能导致代码难以理解和维护</li><li>可能带来安全问题</li></ul></li></ul><p>反射相关内容：</p><p>1、定义： 反射机制是在运行时，对于任意一个类，都能够知道这个类的所有属性和方法；对于任意个对象， 都能够调用它的任意一个方法。在java中，只要给定类的名字，就可以通过反射机制来获得类的所 有信息。 这种动态获取的信息以及动态调用对象的方法的功能称为Java语言的反射机制。</p><p>哪里会用到反射机制？</p><p>jdbc就是典型的反射</p><h3 id="_4、注解" tabindex="-1">4、注解 <a class="header-anchor" href="#_4、注解" aria-label="Permalink to &quot;4、注解&quot;">​</a></h3><h3 id="_5、spi" tabindex="-1">5、SPI <a class="header-anchor" href="#_5、spi" aria-label="Permalink to &quot;5、SPI&quot;">​</a></h3><blockquote><p>SPI 是什么东西</p></blockquote><p>要知道它的作用，需要清楚为什么会有这个机制。</p><p>参考： <a href="https://javaguide.cn/java/basis/java-basic-questions-03.html#spi" target="_blank" rel="noreferrer">https://javaguide.cn/java/basis/java-basic-questions-03.html#spi</a></p><p>参考： <a href="https://pdai.tech/md/java/advanced/java-advanced-spi.html" target="_blank" rel="noreferrer">https://pdai.tech/md/java/advanced/java-advanced-spi.html</a></p><p>可以看一下这句话：SPI（Service Provider Interface），是JDK内置的一种 服务提供发现机制，可以用来启用框架扩展和替换组件。</p><p>Java 会提供一个公开的接口（标准服务接口），第三方会提供该接口的服务实现(不同厂商可以针对同一接口做出不同的实现)</p><p>而Java的<strong>SPI机制可以为某个接口寻找服务实现</strong>。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202401311713463.png" alt="image.png"></p><blockquote><p>SPI 是什么</p></blockquote><ul><li>SPI是一种服务发现机制。</li><li>它允许服务提供者通过配置文件提供服务实现，而服务使用者可以加载这些实现</li></ul><blockquote><p>SPI 实现原理</p></blockquote><ul><li>Java SPI的实现基于<code>ServiceLoader</code>类。</li><li>服务提供者在<code>META-INF/services</code>目录下提供配置文件，其中指定接口的实现类。</li><li><code>ServiceLoader</code>可以加载这些实现。</li></ul><p>关于 SPI 如何为某个公开的标准服务接口找到其实现服务，可以看一个示例。</p><blockquote><p>SPI机制的简单示例</p></blockquote><blockquote><p>网上示例：<a href="https://zhuanlan.zhihu.com/p/28909673" target="_blank" rel="noreferrer">这里在新窗口打开</a></p></blockquote><p>我们现在需要使用一个内容搜索接口，搜索的实现可能是基于文件系统的搜索，也可能是基于数据库的搜索。</p><ul><li>先定义好接口</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public interface Search {</span></span>
<span class="line"><span>    public List&lt;String&gt; searchDoc(String keyword);   </span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>文件搜索实现</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class FileSearch implements Search{</span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public List&lt;String&gt; searchDoc(String keyword) {</span></span>
<span class="line"><span>        System.out.println(&quot;文件搜索 &quot;+keyword);</span></span>
<span class="line"><span>        return null;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>数据库搜索实现</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class DatabaseSearch implements Search{</span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public List&lt;String&gt; searchDoc(String keyword) {</span></span>
<span class="line"><span>        System.out.println(&quot;数据搜索 &quot;+keyword);</span></span>
<span class="line"><span>        return null;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>resources 接下来可以在resources下新建META-INF/services/目录，然后新建接口全限定名的文件：<code>com.cainiao.ys.spi.learn.Search</code>，里面加上我们需要用到的实现类</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>com.cainiao.ys.spi.learn.FileSearch</span></span></code></pre></div><ul><li>测试方法</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class TestCase {</span></span>
<span class="line"><span>    public static void main(String[] args) {</span></span>
<span class="line"><span>        ServiceLoader&lt;Search&gt; s = ServiceLoader.load(Search.class);</span></span>
<span class="line"><span>        Iterator&lt;Search&gt; iterator = s.iterator();</span></span>
<span class="line"><span>        while (iterator.hasNext()) {</span></span>
<span class="line"><span>           Search search =  iterator.next();</span></span>
<span class="line"><span>           search.searchDoc(&quot;hello world&quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>可以看到输出结果：文件搜索 hello world</p><p>如果在<code>com.cainiao.ys.spi.learn.Search</code>文件里写上两个实现类，那最后的输出结果就是两行了。</p><p>这就是因为<code>ServiceLoader.load(Search.class)</code>在加载某接口时，会去<code>META-INF/services</code>下找接口的全限定名文件，再根据里面的内容加载相应的实现类。</p><p>这就是spi的思想，接口的实现由provider实现，provider只用在提交的jar包里的<code>META-INF/services</code>下根据平台定义的接口新建文件，并添加进相应的实现类内容就好。</p><h3 id="_6、序列化和反序列化" tabindex="-1">6、序列化和反序列化 <a class="header-anchor" href="#_6、序列化和反序列化" aria-label="Permalink to &quot;6、序列化和反序列化&quot;">​</a></h3><h3 id="_7、语法糖" tabindex="-1">7、语法糖 <a class="header-anchor" href="#_7、语法糖" aria-label="Permalink to &quot;7、语法糖&quot;">​</a></h3><hr><p>参考：</p><ul><li><a href="https://javaguide.cn/java/basis/java-basic-questions-03.html" target="_blank" rel="noreferrer">https://javaguide.cn/java/basis/java-basic-questions-03.html</a></li></ul>`,103)])])}const g=s(l,[["render",i]]);export{u as __pageData,g as default};
